    def runs(indices):
        out = []
        for x in indices:
            if not out or x > out[-1][-1] + 1:
                out.append([x])
            else:
                out[-1].append(x)
        return out

    col_runs = runs([c for c in range(w) if any(grid[r][c] != 0 for r in range(h))])
    usable_cols = [c for run in col_runs if len(run) > 1 for c in run]
    tile_rows = runs([r for r in range(h) if any(grid[r][c] != 0 for c in usable_cols)])
    usable_rows = [r for run in tile_rows if len(run) > 1 for r in run]
    tile_cols = runs([c for c in range(w) if any(grid[r][c] != 0 for r in usable_rows)])
    tile_rows = [run for run in tile_rows if len(run) > 1]
    tile_cols = [run for run in tile_cols if len(run) > 1]
    centers = {}
    for i, rr in enumerate(tile_rows):
        for j, cc in enumerate(tile_cols):
            r, c = rr[len(rr)//2], cc[len(cc)//2]
            centers[i, j] = grid[r][c]
    base = Counter(centers.values()).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for i in range(len(tile_rows)):
        by_color = {}
        for j in range(len(tile_cols)):
            color = centers[i, j]
            if color != base:
                by_color.setdefault(color, []).append(j)
        for color, positions in by_color.items():
            for a, b in zip(positions, positions[1:]):
                inner_rows = tile_rows[i][1:] if tile_rows[i][-1] == h - 1 else tile_rows[i][1:-1]
                for j in range(a, b):
                    gap = range(tile_cols[j][-1] + 1, tile_cols[j+1][0])
                    for r in inner_rows:
                        for c in gap:
                            out[r][c] = color

    for j in range(len(tile_cols)):
        by_color = {}
        for i in range(len(tile_rows)):
            color = centers[i, j]
            if color != base:
                by_color.setdefault(color, []).append(i)
        for color, positions in by_color.items():
            for a, b in zip(positions, positions[1:]):
                inner_cols = tile_cols[j][1:] if tile_cols[j][-1] == w - 1 else tile_cols[j][1:-1]
                for i in range(a, b):
                    gap = range(tile_rows[i][-1] + 1, tile_rows[i+1][0])
                    for r in gap:
                        for c in inner_cols:
                            out[r][c] = color
    return out

